end

local function RestoreAfterDelay()
	SetSignalMask(SIG_RESTORE)
	Sleep(restore_delay)
	Turn(turret, y_axis, 0, rad(145))
	Turn(sleeve1, x_axis, 0, rad(95))
	Turn(sleeve2, x_axis, 0, rad(95))
end

local function SetMaxReloadTime(reload)
	restore_delay = reload * 2
end

function script.Create()
